INSERT INTO dashboard VALUES(25,48,'home-alternative','HOME-alternative','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":0,"id":25,"links":[],"panels":[{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"custom":{"thresholdsStyle":{"mode":"color","thresholds":[]}},"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":5,"w":4,"x":0,"y":0},"id":2,"options":{"alertCustomMessage":"","alwaysVisibleFilter":false,"autoScroll":false,"browserTabNamePattern":"","collapsedByDefault":false,"customValue":false,"displayMode":"table","emptyValue":false,"favorites":{"enabled":false,"storage":"browser"},"filter":false,"groupSelection":false,"header":true,"isMinimizeForTable":false,"isUseLocalTime":false,"minimizeOutputFormat":"text","padding":10,"persistent":false,"saveSelectedGroup":false,"saveSelectedGroupKey":"","selectedValues":{"showSelected":false},"showGroupTotal":false,"showLabel":false,"showName":false,"showResetButton":false,"showTotal":false,"statusSort":false,"sticky":false,"tabsInOrder":true,"variable":"category"},"pluginVersion":"4.0.0","targets":[{"datasource":{"type":"datasource","uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"volkovlabs-variable-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":26,"w":5,"x":4,"y":0},"id":1,"options":{"afterRender":"const jsonString = context.data[''pvTree''];\nconst data = JSON.parse(jsonString);\n\nfunction redirect(codes, path) {\n  const codesParam = codes.map(code =\u003e `var-pv=${code}`);\n  const codesParamStr = codesParam.join(\"\u0026\");\n  const pathParamStr = path.join(\"\u003e\");\n  // console.log(\"Path:\", path.join(\" → \"));\n  // console.log(\"Codes:\", codesParamStr);\n\n  window.location.href = `http://ted-dev.cl.gemini.edu/d/063032a1-9bfd-4aa0-a7fc-1e79dc1c46ca/telemetry?orgId=1\u0026from=now-12h\u0026to=now\u0026timezone=browser\u0026var-title=${pathParamStr}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n}\n\nfunction buildTree(obj, path = []) {\n  const levelDiv = document.createElement(''div'');\n  levelDiv.className = ''level'';\n\n  for (const key in obj) {\n    const value = obj[key];\n    const node = document.createElement(''div'');\n    node.className = value.codes ? ''node leaf'' : ''node branch'';\n\n    const label = document.createElement(''span'');\n    label.textContent = key;\n\n    const currentPath = [...path, key]; // build full path progressively\n\n    if (value.codes) {\n      label.addEventListener(''click'', () =\u003e redirect(value.codes, currentPath));\n    }\n\n    node.appendChild(label);\n\n    if (!value.codes) {\n      const children = buildTree(value, currentPath);\n      node.appendChild(children);\n    }\n\n    levelDiv.appendChild(node);\n  }\n\n  return levelDiv;\n}\n\nconst treeRoot = document.getElementById(''pvTree'');\ntreeRoot.innerHTML = '''';\ntreeRoot.appendChild(buildTree(data));\n","content":"\u003cdiv id=\"pvTree\" class=\"pvTree\"\u003e\nTable\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"markdown"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"everyRow","styles":"#pvTree {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  font-family: sans-serif;\n}\n\n.level {\n  display:;\n  // flex-wrap: wrap;\n  // gap: 2px;\n  // justify-content: center;\n  margin-bottom: 20px;\n}\n\n.node {\n  // border-radius: 6px;\n  padding: 0px 20px;\n  // background: #fafafa;\n  // cursor: pointer;\n  // display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n\n.node.branch \u003e span {\n  text-decoration: underline;\n  font-weight: bold;\n}\n\n.node.leaf { \n  border-bottom: 1px solid #ccc;\n  border-radius: 5px;\n  margin-bottom: 5px;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.node.leaf:hover {\n  color: ${theme.colors.primary.main};\n  font-weight : bold;\n  cursor: pointer;\n  \n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${category:value}"],["system","${system:text}"]],"queryParams":"","refId":"A","urlPath":"/getSystemTree"}],"title":"New panel","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"custom":{"thresholdsStyle":{"mode":"color","thresholds":[]}},"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":21,"w":4,"x":0,"y":5},"id":3,"options":{"alertCustomMessage":"","alwaysVisibleFilter":false,"autoScroll":false,"browserTabNamePattern":"","collapsedByDefault":false,"customValue":false,"displayMode":"table","emptyValue":false,"favorites":{"enabled":false,"storage":"browser"},"filter":false,"groupSelection":false,"header":true,"isMinimizeForTable":false,"isUseLocalTime":false,"minimizeOutputFormat":"text","padding":10,"persistent":false,"saveSelectedGroup":false,"saveSelectedGroupKey":"","selectedValues":{"maxCount":-1,"showSelected":false},"showGroupTotal":false,"showLabel":false,"showName":false,"showResetButton":false,"showTotal":false,"statusSort":false,"sticky":false,"tabsInOrder":true,"variable":"system"},"pluginVersion":"4.0.0","targets":[{"datasource":{"type":"datasource","uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"volkovlabs-variable-panel"}],"preload":false,"schemaVersion":41,"tags":[],"templating":{"list":[{"allowCustomValue":false,"current":{"text":"subsystems","value":"subsystems"},"description":"","label":"Category","name":"category","options":[{"selected":false,"text":"Instruments","value":"instruments"},{"selected":true,"text":"Subsystems","value":"subsystems"}],"query":"Instruments : instruments, Subsystems : subsystems","type":"custom"},{"allowCustomValue":false,"current":{"text":"mcs","value":"mcs"},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","label":"System","name":"system","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.*"}],"method":"GET","params":[["category","${category}"]],"queryParams":"","urlPath":"/getSystemsByCategory"},"refresh":1,"regex":"","type":"query"}]},"time":{"from":"now-6h","to":"now"},"timepicker":{},"timezone":"browser","title":"HOME-alternative","uid":"283f9687-82db-42d7-b1c4-2d5e06d293c9","version":48}',1,'2025-10-29 18:08:12','2025-11-03 17:36:56',1,1,0,'',8,0,0,'283f9687-82db-42d7-b1c4-2d5e06d293c9',0,NULL,'v0alpha1','aexhjupxl7280a');
INSERT INTO dashboard VALUES(27,62,'telemetry','Telemetry','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"Channel Selector","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());