ackground: #fafafa;\n  // cursor: pointer;\n  // display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n\n.node.branch \u003e span {\n  text-decoration: underline;\n  font-weight: bold;\n}\n\n.node.leaf { \n  border-bottom: 1px solid #ccc;\n  border-radius: 5px;\n  margin-bottom: 5px;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.node.leaf:hover {\n  color: ${theme.colors.primary.main};\n  font-weight : bold;\n  cursor: pointer;\n  \n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${category:value}"],["system","${system:text}"]],"queryParams":"","refId":"A","urlPath":"/getSystemTree"}],"title":"New panel","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"custom":{"thresholdsStyle":{"mode":"color","thresholds":[]}},"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":21,"w":4,"x":0,"y":5},"id":3,"options":{"alertCustomMessage":"","alwaysVisibleFilter":false,"autoScroll":false,"browserTabNamePattern":"","collapsedByDefault":false,"customValue":false,"displayMode":"table","emptyValue":false,"favorites":{"enabled":false,"storage":"browser"},"filter":false,"groupSelection":false,"header":true,"isMinimizeForTable":false,"isUseLocalTime":false,"minimizeOutputFormat":"text","padding":10,"persistent":false,"saveSelectedGroup":false,"saveSelectedGroupKey":"","selectedValues":{"maxCount":-1,"showSelected":false},"showGroupTotal":false,"showLabel":false,"showName":false,"showResetButton":false,"showTotal":false,"statusSort":false,"sticky":false,"tabsInOrder":true,"variable":"system"},"pluginVersion":"4.0.0","targets":[{"datasource":{"type":"datasource","uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"v