desParam.join(\"\u0026\");\n  const pathParamStr = path.join(\"\u003e\");\n  // console.log(\"Path:\", path.join(\" → \"));\n  // console.log(\"Codes:\", codesParamStr);\n\n  window.location.href = `http://ted-dev.cl.gemini.edu/d/063032a1-9bfd-4aa0-a7fc-1e79dc1c46ca/telemetry?orgId=1\u0026from=now-12h\u0026to=now\u0026timezone=browser\u0026var-title=${pathParamStr}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n}\n\nfunction buildTree(obj, path = []) {\n  const levelDiv = document.createElement(''div'');\n  levelDiv.className = ''level'';\n\n  for (const key in obj) {\n    const value = obj[key];\n    const node = document.createElement(''div'');\n    node.className = value.codes ? ''node leaf'' : ''node branch'';\n\n    const label = document.createElement(''span'');\n    label.textContent = key;\n\n    const currentPath = [...path, key]; // build full path progressively\n\n    if (value.codes) {\n      label.addEventListener(''click'', () =\u003e redirect(value.codes, currentPath));\n    }\n\n    node.appendChild(label);\n\n    if (!value.codes) {\n      const children = buildTree(value, currentPath);\n      node.appendChild(children);\n    }\n\n    levelDiv.appendChild(node);\n  }\n\n  return levelDiv;\n}\n\nconst treeRoot = document.getElementById(''pvTree'');\ntreeRoot.innerHTML = '''';\ntreeRoot.appendChild(buildTree(data));\n","content":"\u003cdiv id=\"pvTree\" class=\"pvTree\"\u003e\nTable\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"markdown"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"everyRow","styles":"#pvTree {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  font-family: sans-serif;\n}\n\n.level {\n  display:;\n  // flex-wrap: wrap;\n  // gap: 2px;\n  // justify-content: center;\n  margin-bottom: 20px;\n}\n\n.node {\n  // border-radius: 6px;\n  padding: 0px 20px;\n  // background: #fafafa;\n  // cursor: pointer;\n  // display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n\n.node.branch \u003e span {\n  text-decoration: underline;\n  font-weight: bold;\n}\n\n.node.leaf { \n  border-bottom: 1px solid #ccc;\n  border-radius: 5px;\n  margin-bottom: 5px;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.node.leaf:hover {\n  color: ${theme.colors.primary.main};\n  font-weight : bold;\n  cursor: pointer;\n  \n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${category:value}"],["system","${system:text}"]],"queryParams":"","refId":"A","urlPath":"/getSystemTree"}],"title":"New panel","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"custom":{"thresholdsStyle":{"mode":"color","thresholds":[]}},"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":21,"w":4,"x":0,"y":5},"id":3,"options":{"alertCustomMessage":"","alwaysVisibleFilter":false,"autoScroll":false,"browserTabNamePattern":"","collapsedByDefault":false,"customValue":false,"displayMode":"table","emptyValue":false,"favorites":{"enabled":false,"storage":"browser"},"filter":false,"groupSelection":false,"header":true,"isMinimizeForTable":false,"isUseLocalTime":false,"minimizeOutputFormat":"text","padding":10,"persistent":false,"saveSelectedGroup":false,"saveSelectedGroupKey":"","selectedValues":{"maxCount":-1,"showSelected":false},"showGroupTotal":false,"showLabel":false,"showName":false,"showResetButton":false,"showTotal":false,"statusSort":false,"sticky":false,"tabsInOrder":true,"variable":"system"},"pluginVersion":"4.0.0","targets":[{"datasource":{"type":"datasource","uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"v