INSERT INTO dashboard_version VALUES(272,27,42,0,43,'2025-11-06 19:55:58',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.fields[0].labels[\"Channel\"];\n  console.log(s);\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Datetime"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"A","urlPath":"/getChannels"}],"title":" ","transformations":[{"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":true}}},{"id":"convertFieldType","options":{"conversions":[{"destinationType":"time","targetField":"Datetime"}],"fields":{}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eWeather Data\u003eWind Direction","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":43}','v0alpha1');
INSERT INTO dashboard_version VALUES(273,27,43,0,44,'2025-11-06 20:02:45',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Datetime"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"A","urlPath":"/getChannels"}],"title":" ","transformations":[{"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":false}}},{"id":"convertFieldType","options":{"conversions":[{"destinationType":"time","targetField":"Datetime"}],"fields":{}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"MCS\u003eElevation\u003eGeneral\u003eError","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":44}','v0alpha1');
INSERT INTO dashboard_version VALUES(274,27,44,0,45,'2025-11-06 20:04:28',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"A","urlPath":"/getChannels"}],"title":" ","transformations":[{"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":false}}},{"id":"convertFieldType","options":{"conversions":[{"destinationType":"time","targetField":"Datetime"}],"fields":{}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eSite Monitoring\u003eWFS SDSU temperatures\u003eAll WFS SDSU Temperture (Deg C)","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":45}','v0alpha1');
INSERT INTO dashboard_version VALUES(275,27,45,0,46,'2025-11-06 20:04:40',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"A","urlPath":"/getChannels"}],"title":" ","transformations":[{"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":false}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eSite Monitoring\u003eWFS SDSU temperatures\u003eAll WFS SDSU Temperture (Deg C)","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":46}','v0alpha1');
INSERT INTO dashboard_version VALUES(276,27,46,0,47,'2025-11-06 20:07:28',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value","type":"string"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel","type":"string"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"A","urlPath":"/getChannels"}],"title":" ","transformations":[{"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":false}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eSite Monitoring\u003eWFS SDSU temperatures\u003eAll WFS SDSU Temperture (Deg C)","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":47}','v0alpha1');
INSERT INTO dashboard_version VALUES(277,27,47,0,48,'2025-11-06 20:08:05',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"A","urlPath":"/getChannels"}],"title":" ","transformations":[{"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":false}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eSite Monitoring\u003eWFS SDSU temperatures\u003eP1WFS SDSU Temperture (Deg C)","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":48}','v0alpha1');
INSERT INTO dashboard_version VALUES(278,27,48,0,49,'2025-11-06 20:14:55',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":21,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"A","urlPath":"/getChannels"}],"title":" ","transformations":[{"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":false}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eSite Monitoring\u003eWFS SDSU temperatures\u003eAll WFS SDSU Temperture (Deg C)","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":49}','v0alpha1');
INSERT INTO dashboard_version VALUES(279,27,49,0,50,'2025-11-06 20:15:20',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"A","urlPath":"/getChannels"}],"title":" ","transformations":[{"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":false}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eSite Monitoring\u003eWFS SDSU temperatures\u003eAll WFS SDSU Temperture (Deg C)","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":50}','v0alpha1');
INSERT INTO dashboard_version VALUES(280,27,50,0,51,'2025-11-06 20:22:42',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","transformations":[{"disabled":true,"id":"partitionByValues","options":{"fields":["Channel"],"keepFields":false,"naming":{"asLabels":false}}}],"type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eSite Monitoring\u003eWFS SDSU temperatures\u003eAll WFS SDSU Temperture (Deg C)","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":51}','v0alpha1');
INSERT INTO dashboard_version VALUES(281,27,51,0,52,'2025-11-06 20:23:45',1,'Working fine.','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Direction","value":"GWS\u003eWeather Data\u003eWind Direction"}],"query":"GWS\u003eTelescope temperature sensors\u003eTruss\u003eAir temp.  -X + GWS\u003eTelescope temperature sensors\u003eTruss\u003eSurface temp.  -X","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindDir"],"value":["ws:cpWindDir"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"ws:tpStMtMx","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":52}','v0alpha1');
INSERT INTO dashboard_version VALUES(282,27,52,0,53,'2025-11-06 20:30:17',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"MCS\u003eElevation\u003eGeneral\u003ePosition","value":"MCS\u003eElevation\u003eGeneral\u003ePosition"},"hide":2,"name":"title","options":[{"selected":true,"text":"MCS\u003eElevation\u003eGeneral\u003ePosition","value":"MCS\u003eElevation\u003eGeneral\u003ePosition"}],"query":"MCS\u003eElevation\u003eGeneral\u003ePosition","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["mc:elCurrentPos"],"value":["mc:elCurrentPos"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":53}','v0alpha1');
INSERT INTO dashboard_version VALUES(284,27,53,0,54,'2025-11-06 20:33:50',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"MCS\u003eElevation\u003eGeneral\u003ePosition","value":"MCS\u003eElevation\u003eGeneral\u003ePosition"},"hide":2,"name":"title","options":[{"selected":true,"text":"MCS\u003eElevation\u003eGeneral\u003ePosition","value":"MCS\u003eElevation\u003eGeneral\u003ePosition"}],"query":"MCS\u003eElevation\u003eGeneral\u003ePosition","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["mc:elCurrentPos"],"value":["mc:elCurrentPos"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry Auto","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":54}','v0alpha1');
INSERT INTO dashboard_version VALUES(285,27,54,0,55,'2025-11-06 20:34:00',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"MCS\u003eElevation\u003eGeneral\u003ePosition","value":"MCS\u003eElevation\u003eGeneral\u003ePosition"},"hide":2,"name":"title","options":[{"selected":true,"text":"MCS\u003eElevation\u003eGeneral\u003ePosition","value":"MCS\u003eElevation\u003eGeneral\u003ePosition"}],"query":"MCS\u003eElevation\u003eGeneral\u003ePosition","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["mc:elCurrentPos"],"value":["mc:elCurrentPos"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":55}','v0alpha1');
INSERT INTO dashboard_version VALUES(286,27,55,0,56,'2025-11-06 20:34:19',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"MCS\u003eElevation\u003eGeneral\u003ePosition","value":"MCS\u003eElevation\u003eGeneral\u003ePosition"},"hide":2,"name":"title","options":[{"selected":true,"text":"MCS\u003eElevation\u003eGeneral\u003ePosition","value":"MCS\u003eElevation\u003eGeneral\u003ePosition"}],"query":"MCS\u003eElevation\u003eVirtual Encoders (degrees)\u003eTape Head 1","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["mc:elCurrentPos"],"value":["mc:elCurrentPos"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":56}','v0alpha1');
INSERT INTO dashboard_version VALUES(287,27,56,0,57,'2025-11-07 11:46:13',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","value":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState"},"hide":2,"name":"title","options":[{"selected":true,"text":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","value":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState"}],"query":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["mc:elCurrentPos","mc:elDemandPos","mc:elStateS"],"value":["mc:elCurrentPos","mc:elDemandPos","mc:elStateS"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"mc:elStateS","value":"mc:elStateS"},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"mc:elStateS","value":"mc:elStateS"}],"query":"mc:elStateS","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"RAW : raw, First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"3600","value":"3600"},"label":"Bin (s)","name":"ppBin","options":[{"selected":false,"text":"SECONDS","value":"1"},{"selected":false,"text":"MINUTES","value":"60"},{"selected":true,"text":"HOURS","value":"3600"}],"query":"SECONDS : 1, MINUTES : 60, HOURS : 3600","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-24h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":57}','v0alpha1');
INSERT INTO dashboard_version VALUES(288,27,57,0,58,'2025-11-07 11:47:43',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","value":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState"},"hide":2,"name":"title","options":[{"selected":true,"text":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","value":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState"}],"query":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["mc:elCurrentPos","mc:elDemandPos","mc:elStateS"],"value":["mc:elCurrentPos","mc:elDemandPos","mc:elStateS"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"mc:elStateS","value":"mc:elStateS"},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"mc:elStateS","value":"mc:elStateS"}],"query":"mc:elStateS","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-24h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":58}','v0alpha1');
INSERT INTO dashboard_version VALUES(289,27,58,0,59,'2025-11-07 11:49:47',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","value":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState"},"hide":2,"name":"title","options":[{"selected":true,"text":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","value":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState"}],"query":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["mc:elCurrentPos","mc:elDemandPos","mc:elStateS"],"value":["mc:elCurrentPos","mc:elDemandPos","mc:elStateS"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"mc:elStateS","value":"mc:elStateS"},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"mc:elStateS","value":"mc:elStateS"}],"query":"mc:elStateS","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":false,"text":"RAW","value":"raw"},{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-6h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":59}','v0alpha1');
INSERT INTO dashboard_version VALUES(290,27,59,0,60,'2025-11-07 17:48:26',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":27,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":1,"options":{"afterRender":"const container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n          if (selectedExtraAxisPVs.includes(code)) {\n            selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n            context.grafana.locationService.partial({\n              ''var-pvExtraAxis'': selectedExtraAxisPVs\n            }, true);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n        }, true);\n      })\n\n      //Append (w extra axis) Button\n      createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n        e.stopPropagation();\n        let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n        let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n        let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n        // Adding to pv to query\n        for (const code of arrCodes) {\n          if (!selectedPVs.includes(code)) {\n            selectedPVs.push(code);\n          }\n        }\n        context.grafana.locationService.partial({\n          ''var-pv'': selectedPVs,\n          ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n        }, true);\n\n        if (selectedExtraAxisPVs[0] == \"\") {\n          selectedExtraAxisPVs = arrCodes;\n        }\n        else {\n          selectedExtraAxisPVs.push(...arrCodes);\n        }\n\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n        }, true);\n      })\n\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        context.grafana.locationService.partial({\n          ''var-pv'': arrCodes,\n          ''var-title'': keyDiv.dataset.path\n        }, true);\n        context.grafana.locationService.partial({\n          ''var-pvExtraAxis'': ''''\n        }, true);\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"PV selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["ppType","${ppType}"],["ppBin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getChannels"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","value":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState"},"hide":2,"name":"title","options":[{"selected":true,"text":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState","value":"MCS\u003eElevation\u003eGeneral\u003ePosition + \n MCS\u003eElevation\u003eGeneral\u003eTCS Demand + MCS\u003eElevation\u003eGeneral\u003eState"}],"query":"MCS\u003eElevation\u003eGeneral\u003eDrive Condition + TCS\u003eWFS Demands\u003ePWFS2 X Demand","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["mc:elCurrentPos","mc:elDemandPos","mc:elStateS"],"value":["mc:elCurrentPos","mc:elDemandPos","mc:elStateS"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"def