INSERT INTO alert_rule_version VALUES(52,1,'af1y3syyin18ge','bexhjuqf7ha0wc','Critical',26,0,27,'2025-11-04 18:28:29','CEM temperature delta','Stuck','[{"refId":"CEM temp delta","queryType":"","relativeTimeRange":{"from":60,"to":0},"datasourceUid":"cesb7dv10h3i8b","model":{"alias":"CEM temperature delta","aliasPattern":"","datasource":{"type":"sasaki77-archiverappliance-datasource","uid":"cesb7dv10h3i8b"},"functions":[{"def":{"category":"Options","defaultParams":["true"],"name":"disableExtrapol","params":[{"name":"boolean","options":["true","false"],"type":"string"}]},"params":["true"]},{"def":{"category":"Transform","defaultParams":[],"name":"delta","params":[]},"params":[]}],"instant":false,"intervalMs":1000,"live":false,"maxDataPoints":43200,"operator":"mean","range":true,"refId":"CEM temp delta","regex":false,"stream":false,"strmCap":"","strmInt":"","target":"m2:status.VALE"}},{"refId":"Last CEM Temp. Delta","queryType":"","relativeTimeRange":{"from":0,"to":0},"datasourceUid":"__expr__","model":{"conditions":[{"evaluator":{"params":[],"type":"gt"},"operator":{"type":"and"},"query":{"params":["B"]},"reducer":{"params":[],"type":"last"},"type":"query"}],"datasource":{"type":"__expr__","uid":"__expr__"},"expression":"CEM temp delta","intervalMs":1000,"maxDataPoints":43200,"reducer":"mean","refId":"Last CEM Temp. Delta","settings":{"mode":"dropNN"},"type":"reduce"}},{"refId":"Stuck","queryType":"","relativeTimeRange":{"from":0,"to":0},"datasourceUid":"__expr__","model":{"conditions":[{"evaluator":{"params":[0],"type":"eq"},"operator":{"type":"and"},"query":{"params":["C"]},"reducer":{"params":[],"type":"last"},"type":"query"}],"datasource":{"type":"__expr__","uid":"__expr__"},"expression":"Last CEM Temp. Delta","intervalMs":1000,"maxDataPoints":43200,"refId":"Stuck","type":"threshold"}}]',30,'NoData','Error',30000000000,'{"__dashboardUid__":"9425acc4-9dd7-4569-a80a-66c1e02a5c89","__panelId__":"11"}','',1,1,'[{"receiver":"Testers"}]','','{"editor_settings":{"simplifi