INSERT INTO alert_configuration_history VALUES(3,1,'{"template_files":null,"alertmanager_config":{"route":{"receiver":"grafana-default-email","group_by":["grafana_folder"],"group_wait":"30s","group_interval":"10s","repeat_interval":"10s"},"receivers":[{"name":"grafana-default-email","grafana_managed_receiver_configs":[{"uid":"","name":"email receiver","type":"email","disableResolveMessage":false,"settings":{"addresses":"\u003cexample@email.com\u003e"}},{"uid":"fesr7afzpjgn4c","name":"grafana-default-email","type":"email","disableResolveMessage":false,"settings":{"addresses":"oscar.fuentes@noirlab.edu","message":"value: {{ $values.A.Value }}","singleEmail":false}}]}]}}','d9d6385c3310f37996c2031ec2010b96','v1',1757360767,0,1761248405);
INSERT INTO alert_configuration_history VALUES(4,1,'{"template_files":null,"alertmanager_config":{"route":{"receiver":"grafana-default-email","group_by":["grafana_folder"],"group_wait":"30s","group_interval":"10s","repeat_interval":"10s"},"receivers":[{"name":"grafana-default-email","grafana_managed_receiver_configs":[{"uid":"","name":"email receiver","type":"email","disableResolveMessage":false,"settings":{"addresses":"\u003cexample@email.com\u003e"}},{"uid":"fesr7afzpjgn4c","name":"grafana-default-email","type":"email","disableResolveMessage":false,"settings":{"addresses":"oscar.fuentes@noirlab.edu","message":"value: {{ $values.A.Value }}","singleEmail":false}}]},{"name":"Testers","grafana_managed_receiver_configs":[{"uid":"bf20sahrz4u0we","name":"Testers","type":"email","disableResolveMessage":false,"settings":{"addresses":"oscar.fuentes@noirlab.edu\nmiguel.gomez@noirlab.edu","singleEmail":false}}]}]}}','184d772f2194d6ce4270b714edf1526b','v1',1761313289,0,1763480769);
INSERT INTO library_element VALUES(1,1,0,'bf2n6ddxksr28c','Channel Selector',1,'marcusolsson-dynamictext-panel','','{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"description":"","fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green","value":null},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":6,"options":{"afterRender":"const isHome = context.grafana.replaceVariables(\"${isHome}\");\nconsole.log(isHome);\n\nconst container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\n\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      if (isHome != \"true\") {\n        createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n            if (selectedExtraAxisPVs.includes(code)) {\n              selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n              context.grafana.locationService.partial({\n                ''var-pvExtraAxis'': selectedExtraAxisPVs\n              }, true);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n          }, true);\n        })\n        //Append (w extra axis) Button\n        createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n          // Adding to pv to query\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n          }, true);\n\n\n          if (selectedExtraAxisPVs[0] == \"\") {\n            selectedExtraAxisPVs = arrCodes;\n          }\n          else {\n            selectedExtraAxisPVs.push(...arrCodes);\n          }\n\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n          }, true);\n        })\n      }\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        if (isHome == \"true\") {\n          const codesParam = arrCodes.map(code =\u003e `var-pv=${code}`);\n          const codesParamStr = codesParam.join(\"\u0026\");\n          const pathParamStr = path.join(\"\u003e\");\n          // console.log(\"Path:\", path.join(\" → \"));\n          // console.log(\"Codes:\", codesParamStr);\n          window.location.href = `http://ted-dev.cl.gemini.edu/d/063032a1-9bfd-4aa0-a7fc-1e79dc1c46ca/telemetry?orgId=1\u0026from=now-12h\u0026to=now\u0026timezone=browser\u0026var-title=${pathParamStr}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n        }\n        else {\n          context.grafana.locationService.partial({\n            ''var-pv'': arrCodes,\n            ''var-title'': keyDiv.dataset.path\n          }, true);\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': ''''\n          }, true);\n        }\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":300,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"Channel Selector","type":"marcusolsson-dynamictext-panel"}','2025-10-30 20:17:43',1,'2025-11-04 18:40:41',1,5,'general');
