INSERT INTO resource_migration_log VALUES(1,'create resource_migration_log table',replace('CREATE TABLE IF NOT EXISTS `resource_migration_log` (\n`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL\n, `migration_id` TEXT NOT NULL\n, `sql` TEXT NOT NULL\n, `success` INTEGER NOT NULL\n, `error` TEXT NOT NULL\n, `timestamp` DATETIME NOT NULL\n);','\n',char(10)),1,'','2025-09-08 19:46:05');
INSERT INTO resource_migration_log VALUES(2,'Initialize resource tables','',1,'','2025-09-08 19:46:05');
INSERT INTO resource_migration_log VALUES(3,'drop table resource','DROP TABLE IF EXISTS `resource`',1,'','2025-09-08 19:46:05');
INSERT INTO resource_migration_log VALUES(4,'create table resource',replace('CREATE TABLE IF NOT EXISTS `resource` (\n`guid` TEXT PRIMARY KEY NOT NULL\n, `resource_version` INTEGER NULL\n, `group` TEXT NOT NULL\n, `resource` TEXT NOT NULL\n, `namespace` TEXT NOT NULL\n, `name` TEXT NOT NULL\n, `value` TEXT NULL\n, `action` INTEGER NOT NULL\n, `label_set` TEXT NULL\n);','\n',char(10)),1,'','2025-09-08 19:46:05');
INSERT INTO resource_migration_log VALUES(5,'create table resource, index: 0','CREATE UNIQUE INDEX `UQE_resource_namespace_group_resource_name` ON `resource` (`namespace`,`group`,`resource`,`name`);',1,'','2025-09-08 19:46:05');
INSERT INTO resource_migration_log VALUES(6,'drop table resource_history','DROP TABLE IF EXISTS `resource_history`',1,'','2025-09-08 19:46:05');
INSERT INTO resource_migration_log VALUES(7,'create table resource_history',replace('CREATE TABLE IF NOT EXISTS `resource_history` (\n`guid` TEXT PRIMARY KEY NOT NULL\n, `resource_version` INTEGER NULL\n, `group` TEXT NOT NULL\n, `resource` TEXT NOT NULL\n, `namespace` TEXT NOT NULL\n, `name` TEXT NOT NULL\n, `value` TEXT NULL\n, `action` INTEGER NOT NULL\n, `label_set` TEXT NULL\n);','\n',char(10)),1,'','2025-09-08 19:46:05');
INSERT INTO resource_migration_log VALUES(8,'create table resource_history, index: 0','CREATE UNIQUE INDEX `UQE_resource_history_namespace_group_name_version` ON `resource_history` (`namespace`,`group`,`resource`,`name`,`resource_version`);',1,'','2025-09-08 19:46:05');
