INSERT INTO resource_migration_log VALUES(14,'create table resource_blob',replace('CREATE TABLE IF NOT EXISTS `resource_blob` (\n`uuid` UUID PRIMARY KEY NOT NULL\n, `created` DATETIME NOT NULL\n, `group` TEXT NOT NULL\n, `resource` TEXT NOT NULL\n, `namespace` TEXT NOT NULL\n, `name` TEXT NOT NULL\n, `value` BLOB NOT NULL\n, `hash` TEXT NOT NULL\n, `content_type` TEXT NOT NULL\n);','\n',char(10)),1,'','2025-09-08 19:46:05');
